function longestSubstringSet(s) {
  const cs=new Set();let l=0,max=0;
  for(let r=0;r<s.length;r++){
    while(cs.has(s[r])){cs.delete(s[l]);l++;}
    cs.add(s[r]);
    max=Math.max(max,r-l+1);
  }
  return max;
}

function longestSubstringMap(s) {
  const m=new Map();let l=0,max=0;
  for(let r=0;r<s.length;r++){
    if(m.has(s[r]))l=Math.max(l,m.get(s[r])+1);
    m.set(s[r],r);
    max=Math.max(max,r-l+1);
  }
  return max;
}

