function maxSlidingWindowImpl(nums, k) {
  const dq=[],r=[];
  for(let i=0;i<nums.length;i++){
    if(dq.length&&dq[0]<i-k+1)dq.shift();
    while(dq.length&&nums[dq[dq.length-1]]<=nums[i])dq.pop();
    dq.push(i);
    if(i>=k-1)r.push(nums[dq[0]]);
  }
  return r;
}

