function trapPrecomputed(height) {
  const n=height.length;
  const ml=new Array(n).fill(0),mr=new Array(n).fill(0);
  ml[0]=height[0];
  for(let i=1;i<n;i++)ml[i]=Math.max(ml[i-1],height[i]);
  mr[n-1]=height[n-1];
  for(let i=n-2;i>=0;i--)mr[i]=Math.max(mr[i+1],height[i]);
  let w=0;
  for(let i=0;i<n;i++)w+=Math.min(ml[i],mr[i])-height[i];
  return w;
}

function trapTwoPointer(height) {
  let l=0,r=height.length-1,ml=0,mr=0,w=0;
  while(l<r){
    if(height[l]<height[r]){
      if(height[l]>=ml)ml=height[l];else w+=ml-height[l];
      l++;
    }else{
      if(height[r]>=mr)mr=height[r];else w+=mr-height[r];
      r--;
    }
  }
  return w;
}

