function maxAreaImpl(height) {
  let l=0,r=height.length-1,max=0;
  while(l<r){
    const w=r-l,area=w*Math.min(height[l],height[r]);
    max=Math.max(max,area);
    if(height[l]<height[r])l++;
    else r--;
  }
  return max;
}
